        return []

    rows = len(grid)
    cols = len(grid[0])

    # ---- find minimal horizontal period ----
    w = cols
    for cand in range(1, cols + 1):
        if cols % cand != 0:
            continue
        ok = True
        for i in range(rows):
            for j in range(cand, cols):
                if grid[i][j] != grid[i][j - cand]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            w = cand
            break

    # ---- find minimal vertical period ----
    h = rows
    for cand in range(1, rows + 1):
        if rows % cand != 0:
            continue
        ok = True
        for i in range(cand, rows):
            for j in range(cols):
